 }}</p><p class="help">Resuelve las incidencias antes de liberar este kit.</p><form action="{{ route('operations.inspect',$loan) }}" method="post">@csrf<label for="review-{{ $loan->id }}">Resultado de la revisión funcional</label><textarea id="review-{{ $loan->id }}" name="notes" required minlength="8" rows="2" placeholder="Componentes completos y prueba funcional realizada"></textarea><button class="button">Completar revisión y liberar kit</button><a href="{{ route('incidents') }}" class="button quiet">Ver incidencias</a></form>@endif</div></details>@empty<x-empty title="Todos los préstamos están al día" text="Aquí aparecerán los préstamos activos y las revisiones pendientes."/>@endforelse</div></section>@endsection